target.css:
:root {
  --ink: #17243a;
  --muted: #66758c;
  --card: #ffffff;
  --line: #dbe3ee;
  --soft-blue: #eef5ff;
  --blue: #2878d4;
  --deep-blue: #14529d;
  --green: #24a66a;
  --soft-green: #e8f8ef;
}

.charging-card {
  width: 476px;
  box-sizing: border-box;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--card);
  color: var(--ink);
}

.card-header {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 16px 18px 14px;
  border-bottom: 1px solid var(--line);
}

.station-mark {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  flex: 0 0 auto;
  border-radius: 12px;
  background: var(--blue);
  color: var(--card);
}

.station-mark span {
  font-size: 25px;
  font-weight: 700;
  line-height: 1;
}

.heading {
  min-width: 0;
}

.eyebrow {
  margin: 0 0 2px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

h1 {
  margin: 0;
  font-size: 19px;
  line-height: 1.15;
}

.session-status {
  display: flex;
  align-items: center;
  gap: 5px;
  margin: 0 0 0 auto;
  padding: 6px 9px;
  border-radius: 999px;
  background: var(--soft-green);
  color: var(--green);
  font-size: 12px;
  font-weight: 700;
}

.status-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--green);
}

.metrics {
  display: grid;
  grid-template-columns: 0.92fr 1.08fr;
  gap: 18px;
  padding: 16px 18px;
}

.charge-level {
  padding: 13px;
  border-radius: 13px;
  background: var(--soft-blue);
}

.charge-top {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
}

.charge-label {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
}

.charge-value {
  color: var(--deep-blue);
  font-size: 22px;
  line-height: 1;
}

.battery-track {
  height: 8px;
  margin-top: 13px;
  overflow: hidden;
  border-radius: 999px;
  background: var(--line);
}

.battery-fill {
  display: block;
  width: 82%;
  height: 100%;
  border-radius: inherit;
  background: var(--blue);
}

.detail-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px 16px;
  align-content: center;
}

.detail {
  margin: 0;
}

.detail span,
.detail strong {
  display: block;
}

.detail span {
  margin-bottom: 3px;
  color: var(--muted);
  font-size: 11px;
}

.detail strong {
  font-size: 13px;
  line-height: 1.2;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 11px 18px;
  border-top: 1px solid var(--line);
}

.card-footer p {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
}

.connector {
  color: var(--blue);
  font-size: 14px;
}

button {
  padding: 7px 10px;
  border: 1px solid var(--blue);
  border-radius: 8px;
  background: var(--card);
  color: var(--deep-blue);
  font-size: 12px;
  font-weight: 700;
}

